def ledger_day(posted_at):
    # A ledger day carries the calendar date on which its 05:00 UTC cutoff
    # begins; an instant before 05:00 UTC belongs to the previous date.
    instant = parse_timestamp(posted_at).astimezone(timezone.utc)
    date = instant.date()
    return date if instant.hour >= 5 else date - timedelta(days=1)


def daily_net(month, client):
    begin, end = month_window(month)
    rows = client.list_transactions(created_from=begin, created_to=end)
    totals = {}
    for row in rows:
        date = ledger_day(row["posted_at"]).isoformat()
        payment, refund = totals.get(date, (0, 0))
        if row["kind"] == "payment":
            totals[date] = (payment + row["amount_cents"], refund)
        else:
            totals[date] = (payment, refund + row["amount_cents"])
    days = [
        {
            "date": date,
            "payment_total_cents": payment,
            "refund_total_cents": refund,
            "net_total_cents": payment - refund,
        }
        for date, (payment, refund) in sorted(totals.items())
    ]
    return {"month": month, "days": days}


def dispatch(request):

if request["op"] == "refunds_csv":
    return refunds_csv(request["month"], client)
if request["op"] == "daily_net":
    return daily_net(request["month"], client)

class DailyNetTests(unittest.TestCase):
    def run_cli(self, request):
        result = subprocess.run([sys.executable, "cli.py"], input=json.dumps(request), text=True,
                                capture_output=True, cwd=Path(__file__).resolve().parents[1], check=True)
        return json.loads(result.stdout)

    def test_last_day_extends_to_next_month_cutoff(self):
        request = {"op": "daily_net", "month": "2025-02", "transactions": [
            {"id": "p", "kind": "payment", "posted_at": "2025-02-28T23:00:00Z", "amount_cents": 1000},
            {"id": "r", "kind": "refund", "posted_at": "2025-03-01T04:30:00Z", "amount_cents": 250},
            {"id": "next", "kind": "payment", "posted_at": "2025-03-01T05:00:00Z", "amount_cents": 900},
        ]}
        self.assertEqual(self.run_cli(request), {
            "month": "2025-02",
            "days": [{"date": "2025-02-28", "payment_total_cents": 1000,
                      "refund_total_cents": 250, "net_total_cents": 750}],
        })

    def test_fixture_february_days_compose_reconciliation(self):
        result = self.run_cli({"op": "daily_net", "month": "2025-02"})
        self.assertEqual(result, {
            "month": "2025-02",
            "days": [
                {"date": "2025-02-10", "payment_total_cents": 12000,
                 "refund_total_cents": 0, "net_total_cents": 12000},
                {"date": "2025-02-27", "payment_total_cents": 2500,
                 "refund_total_cents": 0, "net_total_cents": 2500},
                {"date": "2025-02-28", "payment_total_cents": 9700,
                 "refund_total_cents": 400, "net_total_cents": 9300},
            ],
        })

    def test_empty_month_has_no_days(self):
        result = self.run_cli({"op": "daily_net", "month": "2025-02", "transactions": []})
        self.assertEqual(result, {"month": "2025-02", "days": []})

    def test_zero_net_day_is_present(self):
        request = {"op": "daily_net", "month": "2025-02", "transactions": [
            {"id": "p", "kind": "payment", "posted_at": "2025-02-12T12:00:00Z", "amount_cents": 500},
            {"id": "r", "kind": "refund", "posted_at": "2025-02-12T20:00:00Z", "amount_cents": 500},
        ]}
        self.assertEqual(self.run_cli(request), {
            "month": "2025-02",
            "days": [{"date": "2025-02-12", "payment_total_cents": 500,
                      "refund_total_cents": 500, "net_total_cents": 0}],
        })

    def test_month_open_boundary_buckets_by_ledger_day(self):
        request = {"op": "daily_net", "month": "2025-02", "transactions": [
            {"id": "before-open", "kind": "payment", "posted_at": "2025-02-01T04:59:59.999Z", "amount_cents": 999},
            {"id": "open", "kind": "payment", "posted_at": "2025-02-01T05:00:00Z", "amount_cents": 100},
            {"id": "pre-dawn", "kind": "payment", "posted_at": "2025-02-02T04:59:59.999Z", "amount_cents": 200},
        ]}
        self.assertEqual(self.run_cli(request), {
            "month": "2025-02",
            "days": [{"date": "2025-02-01", "payment_total_cents": 300,
                      "refund_total_cents": 0, "net_total_cents": 300}],
        })

    def test_offset_timestamps_bucket_by_utc_instant(self):
        request = {"op": "daily_net", "month": "2025-02", "transactions": [
            {"id": "offset", "kind": "payment", "posted_at": "2025-02-12T02:30:00+02:00", "amount_cents": 300},
        ]}
        self.assertEqual(self.run_cli(request), {
            "month": "2025-02",
            "days": [{"date": "2025-02-11", "payment_total_cents": 300,
                      "refund_total_cents": 0, "net_total_cents": 300}],
        })

    def test_december_close_crosses_into_january_dates(self):
