            {"id": "p-eve", "kind": "payment", "posted_at": "2025-12-31T23:00:00Z", "amount_cents": 500},
            {"id": "r-jan", "kind": "refund", "posted_at": "2026-01-01T04:00:00Z", "amount_cents": 100},
            {"id": "p-next", "kind": "payment", "posted_at": "2026-01-01T05:00:00Z", "amount_cents": 999},
        ]}
        self.assertEqual(self.run_cli(request), {
            "month": "2025-12",
            "days": [{"date": "2025-12-31", "payment_total_cents": 500,
